------------------
---- MONITORS ----
------------------

-- Values the quickshell Settings panel controls.  It writes
-- ~/.config/hypr/shell-settings.lua (a plain `return { ... }` table)
-- and runs `hyprctl reload`, since Hyprland does not watch files that
-- are dofile()d.  Every value falls back to the default here, so a
-- missing or broken file changes nothing.  Change these defaults
-- here; change your own values in the panel.
local S = {}
do
    local ok, t = pcall(dofile, os.getenv("HOME") .. "/.config/hypr/shell-settings.lua")
    if ok and type(t) == "table" then S = t end
end

local function num(v, default, lo, hi)
    if type(v) ~= "number" then return default end
    return math.max(lo, math.min(hi, v))
end
local function int(v, default, lo, hi)
    return math.floor(num(v, default, lo, hi) + 0.5)
end

-- Monitors.  The panel's Displays page writes S.monitors as
--   { ["DP-1"] = { mode = "3840x2160@239.99", position = "0x1440", scale = 1.25 } }
-- and reverts on its own unless the change is confirmed.  Anything
-- missing or malformed falls back to the defaults given here.
local M = type(S.monitors) == "table" and S.monitors or {}

local function monitor(output, def)
    local m = type(M[output]) == "table" and M[output] or {}
    local mode = (type(m.mode) == "string" and m.mode:match("^%d+x%d+@[%d%.]+$"))
                 and m.mode or def.mode
    local pos  = (type(m.position) == "string" and m.position:match("^%-?%d+x%-?%d+$"))
                 and m.position or def.position
    hl.monitor({
        output   = output,
        mode     = mode,
        position = pos,
        scale    = (type(m.scale) == "number" and m.scale >= 0.5 and m.scale <= 3)
                   and m.scale or def.scale,
    })
end

-- Only monitors set up on the Displays page get a rule.  Any other
-- monitor gets Hyprland's own default: its preferred mode, placed
-- automatically.  So a fresh install works on any set of screens.
for output, _ in pairs(M) do
    if type(output) == "string" and output:match("^[%w%-]+$") then
        monitor(output, { mode = "preferred", position = "auto", scale = 1 })
    end
end

