local gapsIn      = int(S.gaps_in,          4,   0, 40)
local gapsOut     = int(S.gaps_out,         1,   0, 60)
local borderSize  = int(S.border_size,      2,   0, 8)
local rounding    = int(S.rounding,         12,  0, 32)
local winActive   = num(S.active_opacity,   1.0, 0.3, 1)
local winInactive = num(S.inactive_opacity, 1.0, 0.3, 1)
local blurSize    = int(S.blur_size,        4,   1, 16)
local blurPasses  = int(S.blur_passes,      3,   1, 4)
local animOn      = S.animations ~= false
-- game mode (quick settings): blur, shadows and animations off, for the
-- highest frame rate; everything returns when it's switched off
local gameMode    = S.game_mode == true
-- For games (Settings > Windows > Gaming):
--   vrr: variable refresh rate (G-SYNC / FreeSync).  0 off, 1 always,
--        2 fullscreen only (the default), 3 fullscreen games and video only
--   direct_scanout: a fullscreen window's frames go straight to the monitor,
--        skipping compositing: less latency and GPU work.  0 off, 1 any
--        fullscreen window, 2 only windows that say they're games (default)
local vrrMode     = int(S.vrr,            2, 0, 3)
local scanout     = int(S.direct_scanout, 2, 0, 2)
local animSpeed   = num(S.anim_speed,       1.0, 0.25, 4)   -- 2 = twice as fast
local repeatRate  = int(S.repeat_rate,      25,  5,  100)   -- keys per second
local repeatDelay = int(S.repeat_delay,     600, 150, 1500) -- ms before repeating
local pointerSpd  = num(S.sensitivity,      0,   -1, 1)
local accelFlat   = S.accel_flat == true
local naturalScr  = S.natural_scroll == true
local followMouse = S.follow_mouse ~= false                 -- false = focus on click

-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in     = gapsIn,
        gaps_out    = gapsOut,
        border_size = borderSize,

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = rounding,
        rounding_power = 2,

        -- transparency of focused and unfocused windows
        active_opacity   = winActive,
        inactive_opacity = winInactive,

        shadow = {
            enabled = not gameMode and (true),
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        -- KWin blurs a rectangle, which is why pills had square corners
        -- there.  Hyprland blurs the layer surface and rounds it to match.
        blur = {
            enabled     = not gameMode,
            size        = blurSize,    -- radius; raise for a heavier frost
            passes      = blurPasses,  -- keep >=3 when size is large, or it banks
            noise       = 0.02,
            contrast    = 1.0,
            brightness  = 1.0,
            vibrancy    = 0.18,
            popups      = true,        -- blur behind menus and tooltips too
            new_optimizations = true,
        },
    },

    animations = {
        enabled = animOn and not gameMode,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
hl.curve("glide",          { type = "bezier", points = { {0.16, 1},    {0.3, 1}     } })

-- Default springs.  A spring's timing comes from its physics, not
-- from an animation's speed, so the panel's speed setting scales the
-- spring itself.  Duration goes with sqrt(mass / stiffness), so
-- stretching time by f means mass * f^2 (or stiffness / f^2), with
-- damping * f keeping the bounce the same shape.
--   slower (f > 1): raise the mass
--   faster (f < 1): raise the stiffness instead, because Hyprland
--                   rejects a spring mass below 0.5
local f = 1 / animSpeed
local springMass, springStiff = 1, 238.1191
if f >= 1 then
    springMass  = springMass * f * f
else
    springStiff = springStiff / (f * f)
end
hl.curve("easy",           { type = "spring", mass = springMass, stiffness = springStiff, dampening = 24.21279333 * f })

-- every animation goes through here so the panel's speed setting
-- scales them all together (Hyprland's speed is a duration: lower
-- is faster)
local function anim(t)
    t.speed = t.speed / animSpeed
    hl.animation(t)
end

anim({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
anim({ leaf = "border",        enabled = true,  speed = 5.39, bezier = "easeOutQuint" })
anim({ leaf = "windows",       enabled = true,  speed = 4.79, spring = "easy" })
anim({ leaf = "windowsIn",     enabled = true,  speed = 4.1,  spring = "easy",         style = "popin 87%" })
anim({ leaf = "windowsOut",    enabled = true,  speed = 1.49, bezier = "linear",       style = "popin 87%" })
anim({ leaf = "fadeIn",        enabled = true,  speed = 1.73, bezier = "almostLinear" })
anim({ leaf = "fadeOut",       enabled = true,  speed = 1.46, bezier = "almostLinear" })
anim({ leaf = "fade",          enabled = true,  speed = 3.03, bezier = "quick" })
anim({ leaf = "layers",        enabled = true,  speed = 3.81, bezier = "easeOutQuint" })
anim({ leaf = "layersIn",      enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "fade" })
anim({ leaf = "layersOut",     enabled = true,  speed = 1.5,  bezier = "linear",       style = "fade" })
anim({ leaf = "fadeLayersIn",  enabled = true,  speed = 1.79, bezier = "almostLinear" })
anim({ leaf = "fadeLayersOut", enabled = true,  speed = 1.39, bezier = "almostLinear" })
-- Switching workspaces (Settings > Windows > Switching workspaces).
-- Only the "workspaces" leaf decides it: workspacesIn and workspacesOut
-- used to be set to a quick fade, which overrode the slide and made the
-- switch look almost instant.  They now follow the same style.
--   slide      side to side, like moving along a row (the default)
--   slidevert  up and down
--   glide      a short slide with a fade: subtler
--   fade       a cross-fade
--   off        instant
local wsStyles = {
    slide     = { style = "slide",           speed = 4.5, bezier = "glide" },
    slidevert = { style = "slidevert",       speed = 4.5, bezier = "glide" },
    glide     = { style = "slidefade 20%",   speed = 4,   bezier = "glide" },
    fade      = { style = "fade",            speed = 3,   bezier = "almostLinear" },
}
local wsChoice = wsStyles[S.ws_anim] and S.ws_anim or (S.ws_anim == "off" and "off" or "slide")
local ws = wsStyles[wsChoice]
for _, leaf in ipairs({ "workspaces", "workspacesIn", "workspacesOut" }) do
    if ws then
        anim({ leaf = leaf, enabled = true, speed = ws.speed, bezier = ws.bezier, style = ws.style })
    else
        anim({ leaf = leaf, enabled = false, speed = 1, bezier = "default" })
    end
end
-- the special (scratchpad) workspace always drops in from above
anim({ leaf = "specialWorkspace", enabled = wsChoice ~= "off", speed = 4, bezier = "glide", style = "slidevert" })
anim({ leaf = "zoomFactor",    enabled = true,  speed = 7,    bezier = "quick" })

