---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})


----------------------------------------------------------------
--  Layer blur
----------------------------------------------------------------

-- Layer surfaces need blur asked for by namespace.  Quickshell's surfaces
-- all use the "quickshell" namespace; rofi uses "rofi".
hl.layer_rule({
    name    = "blur-quickshell",
    match   = { namespace = "^quickshell$" },
    blur    = true,
    ignore_alpha = 0.2,   -- don't blur fully transparent regions
})

hl.layer_rule({
    name    = "blur-rofi",
    match   = { namespace = "^rofi$" },
    blur    = true,
    ignore_alpha = 0.2,
})

-- any key or mouse movement brings the screens back after DPMS off
hl.config({
    misc = {
        mouse_move_enables_dpms = true,
        key_press_enables_dpms  = true,
    },
})

-- Xwayland Scaling
hl.config({
  xwayland = {
    force_zero_scaling = true,
  },
})

hl.config({
    cursor = {
        no_warps = true,
    },
})

-- MUST stay last: whatever sets general.col last wins.  pcall so a
-- missing colors.lua (before the first setwall) can't break the config.
pcall(dofile, os.getenv("HOME") .. "/.config/hypr/colors.lua")
